export const ConnectionDetailSchema = {
	type: "object",
	description:
		"Detailed view of a single Connection — extends {@link ConnectionSummaryDTO ConnectionSummaryDTO} with the\n sealed config serialized to a free-form JSON object (<code>Map&lt;String, Object&gt;</code> →\n <code>type: object, additionalProperties: true</code> in the spec, so it round-trips through\n client codegen). NEVER carries credentials: the encrypted credential blob stays inside the\n entity, and every secret-bearing key of the config itself is stripped by\n <code>redactSensitive</code> before serialization.\n\n <p><b>Why redact here and not with <code>@JsonIgnore</code> on the record component?</b> The very\n same <code>ObjectMapper</code> bean serializes <code>ConnectionConfig</code> into the JSONB\n <code>connection.config</code> column (Hibernate's <code>json_format_mapper</code> is wired to it in\n <code>HibernateJacksonFormatMapperConfig</code>). Annotating the component would therefore drop the\n secret on write and destroy the stored value — the API-boundary filter below is the only place\n the two concerns can be separated.\n\n <p>Mirroring the summary fields (rather than embedding the summary record) keeps\n the JSON shape flat — the API consumer sees one record, not a nested <code>summary</code>\n object.",
	properties: {
		attentionProblem: {
			type: "string",
			enum: [
				"CREDENTIAL_EXPIRING",
				"CREDENTIAL_REVOKED",
				"PROVIDER_SUSPENDED",
				"PROVIDER_CLEANUP_UNCONFIRMED",
			],
		},
		config: {
			type: "object",
			additionalProperties: {},
		},
		createdAt: {
			type: "string",
			format: "date-time",
		},
		credentialsUnreadableSince: {
			type: "string",
			format: "date-time",
		},
		displayName: {
			type: "string",
		},
		family: {
			type: "string",
			enum: ["SCM", "MESSAGING", "DOCUMENTATION"],
		},
		id: {
			type: "integer",
			format: "int64",
		},
		kind: {
			type: "string",
			enum: ["GITHUB", "GITLAB", "SLACK", "OUTLINE"],
		},
		state: {
			type: "string",
			enum: ["PENDING", "ACTIVE", "SUSPENDED", "UNINSTALLED"],
		},
		tokenExpiresAt: {
			type: "string",
			format: "date",
		},
		tokenExpiryCheckedAt: {
			type: "string",
			format: "date-time",
		},
		updatedAt: {
			type: "string",
			format: "date-time",
		},
	},
} as const;

