export const CreateWorkspaceRequestSchema = {
	type: "object",
	description: "Request to create a new workspace",
	properties: {
		accountLogin: {
			type: "string",
			description: "Git provider account login (GitHub org/user or GitLab group path)",
			example: "my-org",
			maxLength: 255,
			minLength: 0,
		},
		accountType: {
			type: "string",
			description: "Type of account (USER or ORG)",
			enum: ["ORG", "USER"],
		},
		displayName: {
			type: "string",
			description: "Human-readable name of the workspace",
			example: "My Workspace",
			maxLength: 120,
			minLength: 0,
		},
		kind: {
			type: "string",
			description: "Integration kind to provision. SLACK flows through OAuth, not this endpoint.",
			enum: ["GITHUB", "GITLAB"],
			example: "GITLAB",
		},
		personalAccessToken: {
			type: "string",
			description:
				"Personal Access Token. Required for both kinds (GitLab API or GitHub PAT). Stored encrypted at rest.",
			example: "glpat-...",
			maxLength: 512,
			minLength: 0,
		},
		repositorySelection: {
			type: "string",
			description:
				"GitLab only. ALL monitors every project of the group, including ones created later; SELECTED monitors only selectedProjectIds. Omitted means ALL.",
			enum: ["ALL", "SELECTED"],
		},
		selectedProjectIds: {
			type: "array",
			description:
				"GitLab project IDs to monitor. Required, and only allowed, when repositorySelection is SELECTED. The server checks each with the token.",
			items: {
				type: "integer",
				format: "int64",
				exclusiveMinimum: 0,
			},
		},
		serverUrl: {
			type: "string",
			description:
				"For GitLab, the default GitLab instance this server reads from, which is also used when omitted; any other instance is refused.",
			example: "https://gitlab.example.com",
		},
		workspaceSlug: {
			type: "string",
			description: "Non-reserved lowercase ASCII DNS label. Consecutive hyphens are prohibited.",
			example: "my-workspace",
			maxLength: 51,
			minLength: 3,
			pattern: "^(?!.*--)[a-z0-9][a-z0-9-]{1,49}[a-z0-9]$",
		},
	},
	required: ["accountLogin", "accountType", "displayName", "kind", "workspaceSlug"],
} as const;

