export const InitiateConnectionResponseSchema = {
	type: "object",
	description:
		"Flat response for <code>POST /workspaces/{workspaceSlug</code>/connections}.\n\n <p>Two outcomes, distinguished by <code>type</code>:\n <ul>\n   <li><code>REDIRECT</code> — OAuth / App-install flows (GitHub, Slack). <code>vendorUrl</code> is the\n       URL to bounce the browser to; the signed OAuth state is already embedded in it.</li>\n   <li><code>LINKED</code> — inline-credential flows (GitLab PAT). <code>connectionId</code> is the\n       newly-created Connection; no further round-trip is needed.</li>\n </ul>\n\n <p>Deliberately a flat record (nullable per-variant fields) rather than a sealed\n <code>oneOf</code> hierarchy: a discriminated union serialises to OpenAPI <code>oneOf +\n discriminator</code>, which the webapp's hey-api react-query transformer mishandles. A flat shape\n round-trips cleanly through code generation, so the webapp consumes the generated client\n instead of a hand-rolled fetch wrapper.",
	properties: {
		connectionId: {
			type: "integer",
			format: "int64",
		},
		type: {
			type: "string",
			enum: ["REDIRECT", "LINKED"],
		},
		vendorUrl: {
			type: "string",
			format: "uri",
		},
	},
	required: ["type"],
} as const;

